//! Generated native collection baselines, without tenant resources or authorization.
//! The Resource blueprints and Inventory catalog remain their declaration owners.
use crate::runtime::{
    AgentCollectionMapping, FieldDefinition, NativeCollectionPlan, WireError,
    validate_native_projection,
};
use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};
use std::collections::{BTreeMap, BTreeSet};

/// Exact generated data carried by this package. Regenerated by the producer, never at install time.
pub const DATA: &str = include_str!("packaged_collections.json");

/// Frozen product prerequisites. Presence does not prove current endpoint eligibility.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Prerequisites {
    /// Inclusive minimum numeric OS version.
    pub minimum_os_version: Option<String>,
    /// Inclusive minimum OS build.
    pub minimum_build: Option<u32>,
    /// Exact permitted editions; an empty set imposes no edition constraint.
    pub editions: BTreeSet<String>,
    /// Exact enrollment modes; not a registration or execution grant.
    pub enrollments: BTreeSet<String>,
    /// Required minimum tool versions.
    pub tools: BTreeMap<String, String>,
    /// Required executor capabilities.
    pub capabilities: BTreeSet<String>,
}

/// One immutable baseline. Consumers explicitly select and authorize local capabilities.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Definition {
    /// Official blueprint identity, distinct from a tenant Resource identity.
    pub id: String,
    /// Exact official blueprint version; no moving latest selection.
    pub version: String,
    /// Presentation category, never a local read grant.
    pub category: String,
    /// Original producer prerequisites, without inferred defaults.
    pub prerequisites: Prerequisites,
    /// Original native plan, including query versions, scope and budgets.
    pub plan: NativeCollectionPlan,
    /// Only the exact fields referenced by this baseline.
    pub fields: Vec<FieldDefinition>,
    /// Original producer mappings; no local field guessing.
    pub mappings: BTreeMap<String, AgentCollectionMapping>,
}

/// Read this package's immutable baselines. This performs no I/O or authorization.
pub fn definitions() -> Result<Vec<Definition>, WireError> {
    let definitions: Vec<Definition> =
        serde_json::from_str(DATA).map_err(|_| WireError::InvalidValue)?;
    let mut identities = BTreeSet::new();
    if definitions.is_empty() || definitions.len() > 128 {
        return Err(WireError::InvalidValue);
    }
    for definition in &definitions {
        if !identities.insert((&definition.id, &definition.version)) {
            return Err(WireError::InvalidValue);
        }
        validate_native_projection(
            &definition.fields,
            &definition.mappings,
            &definition.plan,
            false,
        )?;
    }
    Ok(definitions)
}

/// SHA-256 of the exact packaged data; independent of runtime wire schema identity.
pub fn fingerprint() -> [u8; 32] {
    Sha256::digest(DATA.as_bytes()).into()
}
